const CONFIG = {
  SUPABASE_URL: 'https://tzkvbtozhsrlmcpbrstp.supabase.co',
  SUPABASE_ANON_KEY: 'ВСТАВЬ_SUPABASE_ANON_KEY',
};

function result(body, statusCode = 200) {
  return [{ json: { statusCode, ...body } }];
}

function cleanAnonKey(value) {
  return String(value || '')
    .trim()
    .replace(/^VITE_SUPABASE_ANON_KEY\s*=\s*/, '')
    .replace(/^['"]|['"]$/g, '')
    .trim();
}

function hasPlaceholder(value) {
  return !value || String(value).includes('ВСТАВЬ_');
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ''));
}

function getSupabaseError(error) {
  const rawBody = error?.response?.body || error?.body || null;
  let body = rawBody;
  if (typeof rawBody === 'string') {
    try { body = JSON.parse(rawBody); } catch { body = null; }
  }

  const rawMessage = String(body?.message || error?.message || 'Unknown error');
  const statusMatch = rawMessage.match(/\b([45]\d{2})\b/);
  const status = Number(
    error?.statusCode ||
    error?.response?.statusCode ||
    error?.httpCode ||
    body?.statusCode ||
    statusMatch?.[1] ||
    0
  );
  const message = rawMessage
    .replace(/[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}/g, '[token]')
    .slice(0, 300);

  return {
    supabase_status: status || null,
    supabase_code: body?.code ? String(body.code).slice(0, 40) : null,
    supabase_message: message,
  };
}

const anonKey = cleanAnonKey(CONFIG.SUPABASE_ANON_KEY);
if (hasPlaceholder(anonKey)) {
  return result({ ready: false, error: 'n8n workflow is not configured: replace SUPABASE_ANON_KEY placeholder' }, 500);
}

const request = $input.first().json;
const headers = request.headers || {};
const authorization = headers.authorization || headers.Authorization || '';
const token = authorization.startsWith('Bearer ') ? authorization.slice(7).trim() : '';
if (!token) return result({ ready: false, error: 'Требуется авторизация' }, 401);

const body = request.body || {};
const userId = String(body.user_id || '').trim();
const message = String(body.message || '').trim();

if (!isUuid(userId)) {
  return result({ ready: false, error: 'Некорректный user_id' }, 400);
}
if (!message) {
  return result({ ready: false, error: 'Введите сообщение' }, 400);
}
if (message.length > 4096) {
  return result({ ready: false, error: 'Сообщение не должно превышать 4096 символов' }, 400);
}

let rows;
try {
  rows = await this.helpers.httpRequest({
    method: 'POST',
    url: `${CONFIG.SUPABASE_URL}/rest/v1/rpc/admin_get_telegram_recipient`,
    headers: {
      apikey: anonKey,
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: { p_user_id: userId },
    json: true,
  });
} catch (error) {
  const diagnostic = getSupabaseError(error);
  if (diagnostic.supabase_status === 401) {
    return result({ ready: false, error: 'Supabase отклонил сессию или anon key', diagnostic }, 401);
  }
  if (diagnostic.supabase_status === 403) {
    return result({ ready: false, error: 'Нет доступа к отправке сообщений', diagnostic }, 403);
  }
  if (diagnostic.supabase_status === 404) {
    return result({ ready: false, error: 'Supabase не нашел admin_get_telegram_recipient', diagnostic }, 502);
  }
  if (diagnostic.supabase_status === 400) {
    return result({ ready: false, error: 'Supabase вернул ошибку RPC', diagnostic }, 502);
  }
  return result({ ready: false, error: 'Не удалось проверить получателя в Supabase', diagnostic }, 502);
}

const recipient = Array.isArray(rows) ? rows[0] : rows;
if (!recipient?.chat_id) {
  return result({ ready: false, error: 'У пользователя нет Telegram chat_id' }, 404);
}

return result({
  ready: true,
  chat_id: String(recipient.chat_id),
  message,
}, 200);

const telegram = $input.first().json;

if (telegram?.error) {
  return [{ json: { statusCode: 502, ok: false, error: 'Telegram не принял сообщение' } }];
}

return [{
  json: {
    statusCode: 200,
    ok: true,
    message_id: telegram?.message_id || telegram?.result?.message_id || null,
  },
}];
